/* Cohesive 4-Color Theme: Background #1c2421, Card #2e3832, Accent #74c69d, Text #d8f3dc */
:root {
  --bg-color: #1c2421;
  --card-bg: #2e3832;
  --accent: #74c69d;
  --accent-active: #52b788;
  --accent-wilted: #e07a5f;
  --text-main: #d8f3dc;
  --text-dim: #b7e4c7;
  --border-color: #405347;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1.5rem 1rem;
}

.app-container {
  background-color: var(--card-bg);
  border: 3px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  width: 100%;
  max-width: 420px;
  min-width: 320px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.app-header h1 {
  font-size: 1.5rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-main);
}

.plant-stage {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #161e1a;
  border: 2px dashed var(--border-color);
  border-radius: 8px;
  padding: 1rem;
  width: 180px;
  height: 180px;
}

#plant-canvas {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  width: 140px;
  height: 140px;
}

.thirsty-badge {
  position: absolute;
  top: 8px;
  background-color: var(--accent-wilted);
  color: #fff;
  font-size: 0.85rem;
  font-weight: 700;
  padding: 0.25rem 0.6rem;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5);
  animation: pulse 1s infinite alternate ease-in-out;
}

@keyframes pulse {
  0% { transform: scale(1); }
  100% { transform: scale(1.08); }
}

.status-section {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.status-row {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-dim);
}

.meter-container {
  width: 100%;
  height: 20px;
  background-color: #161e1a;
  border: 2px solid var(--border-color);
  border-radius: 6px;
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  background-color: var(--accent);
  transition: width 0.1s linear, background-color 0.2s ease;
}

.meter-fill.wilted {
  background-color: var(--accent-wilted);
}

.counter-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1rem;
  color: var(--text-dim);
}

.counter-value {
  color: var(--text-main);
  font-size: 1.25rem;
}

.actions-section {
  width: 100%;
}

.btn-water {
  width: 100%;
  background-color: var(--accent);
  color: #132a13;
  border: none;
  border-radius: 6px;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 0.75rem;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.05s ease;
}

.btn-water:hover {
  background-color: var(--accent-active);
}

.btn-water:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.btn-water:active {
  transform: translateY(2px);
}

@media (max-width: 360px) {
  .app-container {
    padding: 1.25rem;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const DRAIN_TIME_MS = 120 * 1000;
  let currentMoisture = 100;
  let waterCount = 0;
  let lastTimestamp = performance.now();

  const canvas = document.getElementById("plant-canvas");
  const ctx = canvas.getContext("2d");
  const moistureBar = document.getElementById("moisture-bar");
  const moistureText = document.getElementById("moisture-text");
  const moistureMeter = document.getElementById("moisture-meter");
  const thirstyBadge = document.getElementById("thirsty-badge");
  const waterCountText = document.getElementById("water-count");
  const waterBtn = document.getElementById("water-btn");

  function drawPixel(gridX, gridY, color, size = 6, offsetX = 18, offsetY = 12) {
    ctx.fillStyle = color;
    ctx.fillRect(offsetX + gridX * size, offsetY + gridY * size, size, size);
  }

  function renderPlant(isWilted) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const potBorder = "#582f0e";
    const potColor = "#7f4f24";
    const stemColor = isWilted ? "#936639" : "#2d6a4f";
    const leafColor = isWilted ? "#c67d5a" : "#52b788";
    const leafShadow = isWilted ? "#8c4a2f" : "#40916c";

    // Draw Pot Rim
    for (let x = 2; x <= 11; x++) {
      drawPixel(x, 11, potBorder);
      drawPixel(x, 12, potColor);
    }
    // Draw Pot Body
    for (let y = 13; y <= 15; y++) {
      const indent = y - 12;
      for (let x = 2 + indent; x <= 11 - indent; x++) {
        drawPixel(x, y, potColor);
      }
      drawPixel(2 + indent, y, potBorder);
      drawPixel(11 - indent, y, potBorder);
    }
    for (let x = 5; x <= 8; x++) {
      drawPixel(x, 16, potBorder);
    }

    // Draw Soil
    for (let x = 4; x <= 9; x++) {
      drawPixel(x, 10, "#331800");
    }

    if (isWilted) {
      // Wilted stem curving right and drooping
      drawPixel(6, 9, stemColor);
      drawPixel(7, 8, stemColor);
      drawPixel(8, 7, stemColor);
      drawPixel(9, 7, stemColor);
      drawPixel(10, 8, stemColor);
      drawPixel(10, 9, leafShadow);

      // Drooped right leaf cluster
      drawPixel(11, 9, leafColor);
      drawPixel(11, 10, leafColor);
      drawPixel(12, 10, leafShadow);

      // Drooped left leaf
      drawPixel(5, 8, leafColor);
      drawPixel(4, 9, leafColor);
      drawPixel(4, 10, leafShadow);
    } else {
      // Healthy upright stem
      for (let y = 5; y <= 9; y++) {
        drawPixel(6, y, stemColor);
        drawPixel(7, y, stemColor);
      }

      // Top Leaves / Sprout
      drawPixel(5, 4, leafColor);
      drawPixel(6, 3, leafColor);
      drawPixel(7, 3, leafColor);
      drawPixel(8, 4, leafColor);
      drawPixel(6, 4, leafShadow);
      drawPixel(7, 4, leafShadow);

      // Left Leaf
      drawPixel(4, 6, leafColor);
      drawPixel(5, 6, leafColor);
      drawPixel(3, 7, leafColor);
      drawPixel(4, 7, leafShadow);

      // Right Leaf
      drawPixel(8, 6, leafColor);
      drawPixel(9, 6, leafColor);
      drawPixel(10, 7, leafColor);
      drawPixel(9, 7, leafShadow);
    }
  }

  function updateUI() {
    const rounded = Math.max(0, Math.min(100, Math.round(currentMoisture)));
    moistureBar.style.width = `${rounded}%`;
    moistureText.textContent = `${rounded}%`;
    moistureMeter.setAttribute("aria-valuenow", rounded);

    const isWilted = currentMoisture < 30;
    if (isWilted) {
      thirstyBadge.removeAttribute("hidden");
      moistureBar.classList.add("wilted");
    } else {
      thirstyBadge.setAttribute("hidden", "");
      moistureBar.classList.remove("wilted");
    }

    renderPlant(isWilted);
  }

  function loop(timestamp) {
    const delta = timestamp - lastTimestamp;
    lastTimestamp = timestamp;

    if (currentMoisture > 0) {
      const drainRate = (100 / DRAIN_TIME_MS) * delta;
      currentMoisture = Math.max(0, currentMoisture - drainRate);
    }

    updateUI();
    requestAnimationFrame(loop);
  }

  waterBtn.addEventListener("click", () => {
    currentMoisture = 100;
    waterCount += 1;
    waterCountText.textContent = waterCount;
    updateUI();
  });

  // Initial render
  updateUI();
  requestAnimationFrame(loop);
});
